data:
EvalCaseV2 {
  "type": "object",
  "required": [
    "id",
    "title",
    "steps",
    "legacyIterations",
    "isNegative",
    "models"
  ],
  "description": "`EvalCase` as projected under `x-mcpjam-eval-vocabulary: 2`: the legacy floor is `legacyIterations`, the exact policy-2 count is `iterations`, the rule override is `assertions`. Every other field is as in `EvalCase`, in the same position.",
  "properties": {
    "judge": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "enabled": {
          "type": "boolean"
        }
      },
      "description": "Per-case judge override. enabled: false skips goal-completion grading for this case."
    },
    "id": {
      "type": "string"
    },
    "declaredId": {
      "type": "string",
      "description": "The case's effective declared id. Absent on cases authored before declared identity existed."
    },
    "title": {
      "type": "string"
    },
    "steps": {
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/components/schemas/EvalTestStep"
      },
      "description": "Ordered test steps. A `prompt` step is a model turn; a single model-free `toolCall` step is a render-check; `assert` steps hold the expectations."
    },
    "expectedOutput": {
      "type": "string"
    },
    "legacyIterations": {
      "type": "integer",
      "minimum": 1,
      "maximum": 10,
      "description": "The legacy per-case count, which the legacy resolver reads as a FLOOR (`max(legacyIterations, suite.minimumIterations)`). Stored as `runs`. Vocabulary 1 spells this field `iterations`; under `x-mcpjam-eval-vocabulary: 2` that key is the exact configured count, so the floor answers to this name (legacy spelling `runs`). NOT the same field as `iterations`: the two are never a both-spellings pair, and a PATCH that names neither leaves the stored floor exactly as it was."
    },
    "iterations": {
      "type": "integer",
      "minimum": 1,
      "description": "The exact per-case count under per-case grading, when the case overrides the suite default. Absent means the case inherits it. Vocabulary 1 spells this field `repetitions`."
    },
    "passThreshold": {
      "type": "number",
      "minimum": 0,
      "maximum": 1,
      "description": "Fraction of this case's trials that must pass, overriding the suite default. Absent means the case inherits it. Never derived from the suite's `minimumAccuracy`, which is a PERCENT under a different resolver."
    },
    "isNegative": {
      "type": "boolean",
      "description": "When true, the case passes if NO tools are called."
    },
    "scenario": {
      "type": "string"
    },
    "intent": {
      "type": "string",
      "minLength": 1,
      "maxLength": 64,
      "pattern": "^\\S(?:[\\s\\S]*\\S)?$",
      "description": "Optional authored analytics grouping label. Must be already trimmed; absent means unlabelled."
    },
    "kind": {
      "type": "string",
      "enum": [
        "capability",
        "regression"
      ],
      "description": "Authored case kind for the simple editor. Absent means the editor derives it from matchOptions."
    },
    "models": {
      "type": "array",
      "items": {
        "type": "object",
        "required": [
          "model"
        ],
        "properties": {
          "model": {
            "type": "string",
            "readOnly": true,
            "description": "COMPUTED in responses: the selection's `modelId` when there is one, else the stored bare id. Accepted on writes as a shorthand: send a bare id and the platform converts it (a hosted id becomes a `hosted` selection, any other a `LegacyModelSelection`)."
          },
          "provider": {
            "type": "string"
          },
          "selection": {
            "allOf": [
              {
                "$ref": "#/components/schemas/RequestedModelSelection"
              }
            ],
            "description": "The saved model choice behind `model` (source, connection, `settings.reasoningEffort`). Absent when the case stores only a bare model id. May be a STORED legacy selection (`LegacyModelSelection`, `source: \"legacy\"`): own key only, never MCPJam credits. The model id beside it is computed from it."
          },
          "selectionOrigin": {
            "type": "string",
            "enum": [
              "backfill"
            ],
            "description": "`backfill` when a conversion (a save of a bare id, or the old-data backfill) chose `selection` rather than a person. Absent when a person chose it, and on rows with no selection."
          }
        }
      }
    },
    "matchOptions": {
      "type": "object",
      "description": "In the public vocabulary (`toolCallOrder: any|in-order|exact`, `extraToolCalls`, `arguments`). Absent when the case sets none: omitted from the response rather than sent as `null`."
    },
    "assertions": {
      "type": "object",
      "description": "The case's rule override. Absent when the case sets none. Vocabulary 1 spells this field `checks`.",
      "properties": {
        "mode": {
          "type": "string",
          "enum": [
            "inherit",
            "replace",
            "extend"
          ]
        },
        "list": {
          "type": "array",
          "items": {
            "$ref": "#/components/schemas/EvalAssertion"
          }
        }
      }
    },
    "import": {
      "$ref": "#/components/schemas/EvalCaseImportClaim"
    },
    "source": {
      "$ref": "#/components/schemas/EvalCaseSource"
    },
    "createdAt": {
      "type": [
        "number",
        "null"
      ]
    },
    "updatedAt": {
      "type": [
        "number",
        "null"
      ]
    },
    "suppressedSuiteStandardCheckIds": {
      "$ref": "#/components/schemas/SuppressedSuiteStandardCheckIds",
      "type": "array",
      "items": {
        "type": "string"
      }
    }
  }
}
EvalCaseCreateRequestV2 {
  "type": "object",
  "required": [
    "title",
    "steps"
  ],
  "description": "Create one case. `title` and a non-empty `steps` array are both required: a case persisted without executable steps could never run. Vocabulary 2 (`x-mcpjam-eval-vocabulary: 2`): `legacyIterations`/`runs` is the floor, `iterations`/`repetitions` the exact count, `assertions`/`checks`/`predicates` the rules; two spellings of one field is a `400`. A canonical client projects a GET into this body rather than echoing both spellings back.",
  "properties": {
    "judge": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "enabled": {
          "type": "boolean"
        }
      },
      "nullable": true,
      "description": "Per-case judge override. enabled: false skips goal-completion grading for this case; null clears the override and restores the suite setting."
    },
    "declaredSuiteId": {
      "type": "string",
      "maxLength": 128,
      "description": "The suite file's own `suite.id`, when THIS request is a suite-file sync.\n\nA CI-owned suite (see `EvalSuiteDetail.managedBy`) refuses configuration writes with `409` and `details.reason: \"CI_OWNED_SUITE_READ_ONLY\"`. Naming the suite's own declared id is how the file writing itself is allowed through: the platform permits the write only when the id matches, so naming any other id refuses exactly as loudly as naming none. Omit it for ordinary edits.\n\nPREFER THE `declaredSuiteId` QUERY PARAMETER on this route. This body field still works here, but these request bodies are strict on every Inspector that predates the CI-owned lock, so a body field is a `400` against an older deployment while an unknown query parameter is simply ignored. The MCPJam SDK and CLI send the query parameter."
    },
    "title": {
      "type": "string",
      "minLength": 1
    },
    "id": {
      "type": "string",
      "pattern": "^[A-Za-z0-9_-]{1,128}$",
      "description": "Stable declared id for the case: the id it answers to in a suite file, an import or a CLI argument. Minted for you when omitted, and unique within the suite. Distinct from the `id` on the response, which is the case's platform row id."
    },
    "steps": {
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/components/schemas/EvalTestStep"
      },
      "description": "REPLACES the case's test definition wholesale when provided."
    },
    "expectedOutput": {
      "type": "string"
    },
    "legacyIterations": {
      "type": "integer",
      "minimum": 1,
      "maximum": 10,
      "description": "The legacy per-case count, which the legacy resolver reads as a FLOOR (`max(legacyIterations, suite.minimumIterations)`). Stored as `runs`. Vocabulary 1 spells this field `iterations`; under `x-mcpjam-eval-vocabulary: 2` that key is the exact configured count, so the floor answers to this name (legacy spelling `runs`). NOT the same field as `iterations`: the two are never a both-spellings pair, and a PATCH that names neither leaves the stored floor exactly as it was."
    },
    "runs": {
      "type": "integer",
      "minimum": 1,
      "maximum": 10,
      "deprecated": true,
      "description": "Legacy spelling of `legacyIterations`. Send one spelling only."
    },
    "iterations": {
      "type": "integer",
      "minimum": 1,
      "maximum": 10,
      "description": "The exact number of iterations this case runs under per-case grading, overriding the suite default (vocabulary 1 spells it `repetitions`). PER-CASE GRADING ONLY: on a suite decided by the suite-wide accuracy threshold this is a VALIDATION_ERROR naming the criterion change that would make it readable, because that criterion takes the count from the case's own `legacyIterations` raised to the suite's `minimumIterations` and would never read this. A CREATE that names this but no `legacyIterations` stores the floor at the same value; a CREATE that names neither stores a floor of 1. Capped at 10."
    },
    "repetitions": {
      "type": "integer",
      "minimum": 1,
      "maximum": 10,
      "description": "Legacy spelling of `iterations`. Send one spelling only.",
      "deprecated": true
    },
    "passThreshold": {
      "type": "number",
      "minimum": 0,
      "maximum": 1,
      "description": "Per-case pass threshold FRACTION: the share of this case's own iterations that must pass. PER-CASE GRADING ONLY: on a suite decided by the suite-wide accuracy threshold this is a VALIDATION_ERROR, for the same reason as the count: that criterion has one percentage over the whole run and no per-case threshold to override."
    },
    "isNegative": {
      "type": "boolean"
    },
    "scenario": {
      "type": "string"
    },
    "intent": {
      "type": "string",
      "minLength": 1,
      "maxLength": 64,
      "pattern": "^\\S(?:[\\s\\S]*\\S)?$",
      "description": "Optional authored analytics grouping label. Must be already trimmed."
    },
    "kind": {
      "type": "string",
      "enum": [
        "capability",
        "regression"
      ],
      "description": "Authored case kind for the simple editor. Absent means the editor derives it from matchOptions."
    },
    "models": {
      "type": "array",
      "items": {
        "type": "object",
        "required": [
          "model"
        ],
        "properties": {
          "model": {
            "type": "string"
          },
          "provider": {
            "type": "string",
            "description": "Derived from a `provider/model` id when omitted."
          },
          "selection": {
            "allOf": [
              {
                "$ref": "#/components/schemas/RequestedModelSelection"
              }
            ],
            "description": "The saved model choice behind `model` (source, connection, `settings.reasoningEffort`). Must be FOR `model`. On a `models` PATCH an entry that omits `selection` KEEPS the case's existing selection for that model; `null` drops it."
          }
        }
      }
    },
    "matchOptions": {
      "type": [
        "object",
        "null"
      ],
      "description": "Tool-call match options in either vocabulary: public (`toolCallOrder: any|in-order|exact`, `extraToolCalls`, `arguments`) or internal (`toolCallOrder: ignore|superset|strict`, `maxExtraToolCalls`, `argumentMatching`), never both in one object. On update, fields you omit keep their current values. `null` clears the case override and inherits the suite's."
    },
    "assertions": {
      "type": [
        "object",
        "null"
      ],
      "description": "The case's rule override (legacy spellings `checks`, `predicates`). `null` clears it. Send exactly one spelling.",
      "properties": {
        "mode": {
          "type": "string",
          "enum": [
            "inherit",
            "replace",
            "extend"
          ]
        },
        "list": {
          "type": "array",
          "items": {
            "$ref": "#/components/schemas/EvalAssertion"
          }
        }
      }
    },
    "checks": {
      "type": [
        "object",
        "null"
      ],
      "description": "Legacy spelling of `assertions`. Send one spelling only.",
      "properties": {
        "mode": {
          "type": "string",
          "enum": [
            "inherit",
            "replace",
            "extend"
          ]
        },
        "list": {
          "type": "array",
          "items": {
            "$ref": "#/components/schemas/EvalAssertion"
          }
        }
      },
      "deprecated": true
    },
    "predicates": {
      "type": [
        "object",
        "null"
      ],
      "description": "Legacy spelling of `assertions`. Send one spelling only.",
      "properties": {
        "mode": {
          "type": "string",
          "enum": [
            "inherit",
            "replace",
            "extend"
          ]
        },
        "list": {
          "type": "array",
          "items": {
            "$ref": "#/components/schemas/EvalAssertion"
          }
        }
      },
      "deprecated": true
    },
    "import": {
      "$ref": "#/components/schemas/EvalCaseImportClaim"
    },
    "source": {
      "$ref": "#/components/schemas/EvalCaseSource"
    },
    "suppressedSuiteStandardCheckIds": {
      "$ref": "#/components/schemas/SuppressedSuiteStandardCheckIds",
      "type": "array",
      "items": {
        "type": "string"
      }
    }
  },
  "additionalProperties": false,
  "allOf": [
    {
      "not": {
        "required": [
          "legacyIterations",
          "runs"
        ]
      }
    },
    {
      "not": {
        "required": [
          "iterations",
          "repetitions"
        ]
      }
    },
    {
      "not": {
        "required": [
          "assertions",
          "checks"
        ]
      }
    },
    {
      "not": {
        "required": [
          "assertions",
          "predicates"
        ]
      }
    },
    {
      "not": {
        "required": [
          "checks",
          "predicates"
        ]
      }
    }
  ]
}
EvalCaseUpdateRequestV2 {
